function normalizePhone(value) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.startsWith('0')) digits = `62${digits.slice(1)}`;
  if (digits.startsWith('8')) digits = `62${digits}`;
  return digits;
}

function prettyDate(iso) {
  const [year, month, day] = String(iso || '').split('-');
  return year && month && day ? `${day}/${month}/${year}` : String(iso || '-');
}

const payload = $input.first().json || {};
if (payload.status !== 'ok') return [];
const reminders = Array.isArray(payload.reminders) ? payload.reminders : [];
const config = $('Konfigurasi Workflow').first().json || {};
const portal = String(config.portalUrl || 'https://edu.pkbmtunasilmu.web.id').replace(/\/$/, '');

return reminders
  .map((reminder) => {
    const phone = normalizePhone(reminder.phone);
    const rows = Array.isArray(reminder.missingDates) ? reminder.missingDates : [];
    const lines = rows.map((row, index) => {
      const moved = row.actualDate ? `, dipindah ke ${prettyDate(row.actualDate)}` : '';
      return `${index + 1}. ${row.classLabel} — ${prettyDate(row.date)}${moved} (${row.reason})`;
    });
    const message = [
      '*Pengingat Presensi Peserta Didik*',
      '',
      `Assalamu’alaikum ${reminder.tutorName || 'Tutor'},`,
      `Mohon melengkapi presensi KBM Semester ${payload.semester || '-'} Tahun Ajaran ${payload.tahunAjaran || '-'}.`,
      '',
      `Ditemukan ${rows.length} tanggal/kelas yang belum lengkap:`,
      ...lines,
      '',
      `Silakan buka: ${portal}`,
      'Pilih menu Presensi Mingguan, lalu lengkapi checklist siswa, tanda tangan tutor, dan foto bukti KBM.',
      '',
      'Pesan ini dikirim otomatis oleh Tunas Ilmu Learn.'
    ].join('\n');

    return {
      json: {
        phone,
        tutorId: String(reminder.tutorId || ''),
        tutorName: String(reminder.tutorName || 'Tutor'),
        missingCount: rows.length,
        missingDates: rows,
        message
      }
    };
  })
  .filter((item) => item.json.phone && item.json.missingCount > 0);
